namespace SkyCastWeather;

internal static class Program
{
    [STAThread]
    private static void Main()
    {
        // Generated by the .NET 8 Windows Forms template support.
        ApplicationConfiguration.Initialize();

        // Show unexpected errors in a message box instead of crashing silently.
        Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);
        Application.ThreadException += (_, e) =>
            MessageBox.Show(e.Exception.Message, "SkyCast Weather", MessageBoxButtons.OK, MessageBoxIcon.Error);

        Application.Run(new Forms.MainForm());
    }
}
